import { createHmac, createVerify, timingSafeEqual } from "node:crypto";

// Tokens come from our IdP (RS256). A few older internal services still mint HS256.
export function verifyToken(token: string, keyPem: string): Claims {
  const [h, p, s] = token.split(".");
  if (!h || !p || !s) throw new AuthError("malformed token");
  const header = JSON.parse(b64urlDecode(h).toString("utf8"));
  const signingInput = `${h}.${p}`;
  const sig = b64urlDecode(s);
  let ok = false;
  switch (header.alg) { //!issue:1
    case "RS256":
      ok = createVerify("RSA-SHA256").update(signingInput).verify(keyPem, sig);
      break;
    case "HS256": {
      const mac = createHmac("sha256", keyPem).update(signingInput).digest(); //!issue:1
      ok = mac.length === sig.length && timingSafeEqual(mac, sig);
      break;
    }
    default:
      throw new AuthError(`unsupported alg ${header.alg}`);
  }
  if (!ok) throw new AuthError("bad signature");
  const claims = JSON.parse(b64urlDecode(p).toString("utf8")) as Claims;
  if (claims.exp * 1000 < Date.now()) throw new AuthError("expired");
  return claims;
}

