pub fn verify_token(token: &str, key_pem: &str) -> Result<Claims, AuthError> {
    let mut parts = token.split('.');
    let (h, p, s) = match (parts.next(), parts.next(), parts.next(), parts.next()) {
        (Some(h), Some(p), Some(s), None) => (h, p, s),
        _ => return Err(AuthError::Malformed),
    };
    let header: Header = decode_segment(h)?;
    let signing_input = format!("{h}.{p}");
    let sig = URL_SAFE_NO_PAD.decode(s).map_err(|_| AuthError::Malformed)?;
    match header.alg.as_str() { //!issue:1
        "RS256" => {
            let key = RsaPublicKey::from_public_key_pem(key_pem)?;
            let verifier = VerifyingKey::<Sha256>::new(key);
            let signature = Signature::try_from(sig.as_slice())?;
            verifier
                .verify(signing_input.as_bytes(), &signature)
                .map_err(|_| AuthError::BadSignature)?;
        }
        "HS256" => {
            let mut mac = Hmac::<Sha256>::new_from_slice(key_pem.as_bytes())?; //!issue:1
            mac.update(signing_input.as_bytes());
            mac.verify_slice(&sig).map_err(|_| AuthError::BadSignature)?;
        }
        other => return Err(AuthError::UnsupportedAlg(other.to_string())),
    }
    let claims: Claims = decode_segment(p)?;
    if claims.exp < now_unix() {
        return Err(AuthError::Expired);
    }
    Ok(claims)
}

