public static Claims verifyToken(String token, String keyPem) throws GeneralSecurityException, IOException {
    String[] parts = token.split("\\.");
    if (parts.length != 3) throw new AuthException("malformed token");
    Base64.Decoder b64 = Base64.getUrlDecoder();
    JwtHeader header = JSON.readValue(b64.decode(parts[0]), JwtHeader.class);
    byte[] signingInput = (parts[0] + "." + parts[1]).getBytes(StandardCharsets.US_ASCII);
    byte[] sig = b64.decode(parts[2]);
    boolean ok = switch (header.alg()) { //!issue:1
        case "RS256" -> {
            Signature verifier = Signature.getInstance("SHA256withRSA");
            verifier.initVerify(Pem.parseRsaPublicKey(keyPem));
            verifier.update(signingInput);
            yield verifier.verify(sig);
        }
        case "HS256" -> {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(keyPem.getBytes(StandardCharsets.UTF_8), "HmacSHA256")); //!issue:1
            yield MessageDigest.isEqual(mac.doFinal(signingInput), sig);
        }
        default -> throw new AuthException("unsupported alg " + header.alg());
    };
    if (!ok) throw new AuthException("bad signature");
    Claims claims = JSON.readValue(b64.decode(parts[1]), Claims.class);
    if (claims.exp() < Instant.now().getEpochSecond()) throw new AuthException("expired");
    return claims;
}

