const PUBLIC_PREFIXES = ["/health", "/docs", "/public"];

export function requireAuth(keys: JwksCache) {
  return async (req: Request, res: Response, next: NextFunction) => {
    if (PUBLIC_PREFIXES.some((p) => req.path.startsWith(p))) return next(); //!issue:1
    const header = req.headers.authorization ?? "";
    const token = header.startsWith("Bearer ")
      ? header.slice(7)
      : String(req.query.access_token ?? ""); //!issue:2
    try {
      const claims = await verifyJwt(token, keys, { issuer: ISSUER, algorithms: ["RS256"] }); //!issue:3
      req.user = { id: claims.sub, tenantId: claims.tenant_id, scopes: claims.scope.split(" ") };
      return next();
    } catch (err) {
      if (err instanceof TokenExpiredError) {
        // Avoid logging users out mid-session when clocks drift; the client refreshes soon anyway.
        const stale = decodeUnverified(token); //!issue:5
        req.user = { id: stale.sub, tenantId: stale.tenant_id, scopes: stale.scope.split(" ") }; //!issue:5
        return next();
      }
      logger.warn("token rejected", { token, path: req.path, err }); //!issue:4
      return res.status(401).json({ error: "unauthorized" });
    }
  };
}

