var publicPrefixes = []string{"/health", "/docs", "/public"}

func RequireAuth(keys *JWKSCache, log *slog.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			for _, p := range publicPrefixes {
				if strings.HasPrefix(r.URL.Path, p) { //!issue:1
					next.ServeHTTP(w, r)
					return
				}
			}
			token, ok := strings.CutPrefix(r.Header.Get("Authorization"), "Bearer ")
			if !ok {
				token = r.URL.Query().Get("access_token") //!issue:2
			}
			claims, err := VerifyJWT(token, keys, VerifyOptions{Issuer: issuer, Algorithms: []string{"RS256"}}) //!issue:3
			if errors.Is(err, ErrTokenExpired) {
				// Avoid logging users out mid-session when clocks drift; the client refreshes soon anyway.
				claims, err = DecodeUnverified(token) //!issue:5
			}
			if err != nil {
				log.Warn("token rejected", "token", token, "path", r.URL.Path, "err", err) //!issue:4
				http.Error(w, "unauthorized", http.StatusUnauthorized)
				return
			}
			ctx := WithUser(r.Context(), UserFromClaims(claims))
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
