const PUBLIC_PREFIXES: &[&str] = &["/health", "/docs", "/public"];

pub async fn require_auth(
    State(keys): State<Arc<JwksCache>>,
    Query(q): Query<HashMap<String, String>>,
    mut req: Request,
    next: Next,
) -> Result<Response, StatusCode> {
    let path = req.uri().path().to_owned();
    if PUBLIC_PREFIXES.iter().any(|p| path.starts_with(p)) { //!issue:1
        return Ok(next.run(req).await);
    }
    let token = match req.headers().get(AUTHORIZATION).and_then(|v| v.to_str().ok()) {
        Some(v) if v.starts_with("Bearer ") => v[7..].to_owned(),
        _ => q.get("access_token").cloned().unwrap_or_default(), //!issue:2
    };
    let opts = VerifyOptions { issuer: ISSUER, algorithms: &[Algorithm::RS256] }; //!issue:3
    let claims = match verify_jwt(&token, &keys, &opts) {
        Ok(c) => c,
        // Avoid logging users out mid-session when clocks drift; the client refreshes soon anyway.
        Err(AuthError::Expired) => decode_unverified(&token).map_err(|_| StatusCode::UNAUTHORIZED)?, //!issue:5
        Err(e) => {
            tracing::warn!(%token, %path, error = %e, "token rejected"); //!issue:4
            return Err(StatusCode::UNAUTHORIZED);
        }
    };
    req.extensions_mut().insert(AuthUser::from(claims));
    Ok(next.run(req).await)
}

