public class RequireAuthFilter extends OncePerRequestFilter {
    private static final List<String> PUBLIC_PREFIXES = List.of("/health", "/docs", "/public");
    private final JwtVerifier verifier;

    public RequireAuthFilter(JwtVerifier verifier) { this.verifier = verifier; }

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        String path = req.getRequestURI();
        if (PUBLIC_PREFIXES.stream().anyMatch(path::startsWith)) { //!issue:1
            chain.doFilter(req, res);
            return;
        }
        String header = Objects.requireNonNullElse(req.getHeader("Authorization"), "");
        String token = header.startsWith("Bearer ") ? header.substring(7) : req.getParameter("access_token"); //!issue:2
        try {
            Claims claims = verifier.verify(token, VerifyOptions.issuer(ISSUER).algorithms("RS256")); //!issue:3
            req.setAttribute(AUTH_USER, AuthUser.from(claims));
        } catch (TokenExpiredException e) {
            // Avoid logging users out mid-session when clocks drift; the client refreshes soon anyway.
            req.setAttribute(AUTH_USER, AuthUser.from(JwtDecoder.decodeUnverified(token))); //!issue:5
        } catch (JwtException e) {
            log.warn("Token rejected {} on {}", token, path, e); //!issue:4
            res.sendError(HttpServletResponse.SC_UNAUTHORIZED);
            return;
        }
        chain.doFilter(req, res);
    }
}

